import{_ as i,o as a,c as e,aO as h}from"./chunks/framework.vjUPZZJn.js";const k=JSON.parse('{"title":"zsh 历史记录损坏的修复","description":"","frontmatter":{"date":"2026-09-24T21:30:00.000Z","title":"zsh 历史记录损坏的修复","source":[["1-知识/工具/Linux环境/zsh 历史记录损坏修复"]],"tags":["工具","问题排查","Linux","zsh"],"categories":["工具"],"permalink":"/pages/2b360b"},"headers":[],"relativePath":"工具/zsh 历史记录损坏的修复.md","filePath":"工具/zsh 历史记录损坏的修复.md","lastUpdated":1790247621000}'),l={name:"工具/zsh 历史记录损坏的修复.md"};function t(n,s,r,p,d,o){return a(),e("div",null,[...s[0]||(s[0]=[h(`<h1 id="zsh-历史记录损坏的修复" tabindex="-1">zsh 历史记录损坏的修复 <a class="header-anchor" href="#zsh-历史记录损坏的修复" aria-label="Permalink to &quot;zsh 历史记录损坏的修复&quot;">​</a></h1> <p>zsh 启动时如果报 <code>zsh: corrupt history file /home/user/.zsh_history</code>，说明历史文件已经损坏，zsh 拒绝加载它。修复思路很简单：用 <code>strings</code> 把文件里的不可打印字符剥离，重建一份能正常解析的历史文件，全程不需要重启终端。</p> <h2 id="损坏的常见原因" tabindex="-1">损坏的常见原因 <a class="header-anchor" href="#损坏的常见原因" aria-label="Permalink to &quot;损坏的常见原因&quot;">​</a></h2> <ul><li>历史文件中混入了不可打印字符，例如误把二进制内容粘贴进了终端</li> <li>多个 shell 会话同时写入同一个历史文件，写入过程互相干扰</li> <li>写入历史时进程被异常终止，留下不完整的记录</li></ul> <h2 id="修复步骤" tabindex="-1">修复步骤 <a class="header-anchor" href="#修复步骤" aria-label="Permalink to &quot;修复步骤&quot;">​</a></h2> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                       # 进入 home 目录</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .zsh_history</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .zsh_history_bad</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # 把损坏的历史文件改名备份</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .zsh_history_bad</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .zsh_history</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 只保留可打印字符，重建历史文件</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">fc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .zsh_history</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                         # 在当前会话重新加载历史</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>逐行说明：</p> <ul><li><code>mv</code> 先把原文件改名，损坏的原始数据保留在 <code>.zsh_history_bad</code> 里，修复失败也不会丢数据</li> <li><code>strings</code> 只输出文件中的可打印文本，混入的二进制字符被剥离，zsh 即可正常解析重建后的文件</li> <li><code>fc -R</code> 把重建后的历史读回当前 shell；省略这一步则需要重开终端才能恢复</li></ul> <p>重建后如果发现个别命令丢了，可以从 <code>.zsh_history_bad</code> 里人工挑回——大部分行仍然是完好的，只是个别行夹带坏字符。确认无误后再删除备份。</p> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>报错本质是历史文件里出现了 zsh 无法解析的内容，剥离不可打印字符即可恢复</li> <li>四步操作：改名备份、<code>strings</code> 重建、<code>fc -R</code> 重载，无需重启终端</li> <li>修复不改变写入行为；如果损坏反复出现，优先排查是否有多个会话在同时写同一个历史文件</li></ul>`,20)])])}const _=i(l,[["render",t]]);export{k as __pageData,_ as default};
